// Patient-owner reply. Delayed acceptance cannot animate a cancelled/newer provider episode.
params ["_patient", "_medic", "_episode", "_accepted", "_epoch", "_providerOwner", "_leaseUntil"];
if (isNull _medic || {!local _medic}) exitWith {};
private _same = (_medic getVariable ["ACME_hang_Start", -2]) == _episode
    && {(_medic getVariable ["ACME_hang_Patient", objNull]) isEqualTo _patient};
if (!_same || {!(_medic getVariable ["ACME_hang_Active", false])}) exitWith {
    if (_accepted) then {[_patient, "hangBagRelease", [_medic, _episode]] call ACME_fnc_ownerDispatch;};
};
if (!_accepted || {_leaseUntil <= serverTime} || {!alive _medic} || {_medic getVariable ["ACE_isUnconscious", false]}
    || {_providerOwner != owner _medic}
    || {_epoch != ([_patient] call ACME_fnc_clinicalEpoch)}
    || {_epoch != (_medic getVariable ["ACME_hang_ClaimEpoch", -1])}
    || {_patient getVariable ["ACME_clinicalRestoring", false]}
    || {!isNull objectParent _medic}
    || {_medic distance _patient > (missionNamespace getVariable ["ACME_hang_leash", 3])}
    || {(_medic getVariable ["ACME_hang_PlayerBound", false]) && {!(_medic isEqualTo ACE_player)}}
    || {!(missionNamespace getVariable ["ACME_sys_hang", true])}) exitWith {
    [true, _medic] call ACME_fnc_hangBagStop;
};
_medic setVariable ["ACME_hang_ClaimAckAt", (_leaseUntil - 6) max (_medic getVariable ["ACME_hang_ClaimAckAt", 0]), false];
// Renewals/duplicate ACKs never repeat props, input handlers or the raised-bag animation.
if (_medic getVariable ["ACME_hang_Claimed", false]) exitWith {};
_medic setVariable ["ACME_hang_Claimed", true, false];
[_medic, _patient, _medic getVariable ["ACME_hang_Part", ""],
    _medic getVariable ["ACME_hang_FluidType", "saline"]] call ACME_fnc_hangBagActivate;

// Unscheduled patient-owner arbitration. An unexpired lease wins even before the
// provider's Active flag replicates. No inventory, dose, patient-life or animation policy here.
params ["_patient", "_operation", "_args"];
if (isNull _patient || {!local _patient}) exitWith {false};
_args params [["_medic", objNull, [objNull]], ["_episode", -1, [0]],
    ["_flow", 1.75, [0]], ["_epoch", -1, [0]], ["_providerOwner", -1, [0]]];
private _holder = _patient getVariable ["ACME_hang_Medic", objNull];
private _heldEpisode = _patient getVariable ["ACME_hang_Episode", -2];
private _exact = _holder isEqualTo _medic && {_heldEpisode == _episode};
if (_operation == "release") exitWith {
    if (_exact) then {
        _patient setVariable ["ACME_hang_flowMult", 1, true];
        _patient setVariable ["ACME_hang_Medic", objNull, true];
        _patient setVariable ["ACME_hang_Episode", -1, true];
        _patient setVariable ["ACME_hang_LeaseUntil", -1, true];
    };
    _exact
};
if !(_operation in ["claim", "renew"]) exitWith {false};
private _now = serverTime;
private _valid = !isNull _medic && {alive _medic} && {finite _episode} && {_episode >= 0}
    && {finite _flow} && {_providerOwner == owner _medic}
    && {!(_medic getVariable ["ACE_isUnconscious", false])}
    && {isNull objectParent _medic}
    && {_medic distance _patient <= (missionNamespace getVariable ["ACME_hang_leash", 3])}
    && {_epoch == ([_patient] call ACME_fnc_clinicalEpoch)}
    && {!(_patient getVariable ["ACME_clinicalRestoring", false])}
    && {missionNamespace getVariable ["ACME_sys_hang", true]};
private _leaseUntil = _patient getVariable ["ACME_hang_LeaseUntil", -1];
private _holderValid = !isNull _holder && {alive _holder} && {
    if (_leaseUntil >= 0) then {
        _leaseUntil > _now && {(_patient getVariable ["ACME_hang_LeaseEpoch", -1]) == _epoch}
    } else {
        // Preserve a pre-upgrade active holder rather than steal its workspace.
        _holder getVariable ["ACME_hang_Active", false]
    }
};
private _accepted = _valid && {
    if (_operation == "renew") then {
        _exact && {_leaseUntil > _now}
    } else {
        // An old request cannot reacquire a cancelled hold long after its timeout.
        _now - _episode <= 5 && {!_holderValid || {_exact}}
    }
};
if (_accepted) then {
    if (!_exact) then {
        _patient setVariable ["ACME_hang_Medic", _medic, true];
        _patient setVariable ["ACME_hang_Episode", _episode, true];
        _patient setVariable ["ACME_hang_LeaseEpoch", _epoch, true];
    };
    _patient setVariable ["ACME_hang_LeaseUntil", _now + 6, true];
    private _nextFlow = (_flow max 1) min 5;
    if ((_patient getVariable ["ACME_hang_flowMult", 1]) != _nextFlow) then {
        _patient setVariable ["ACME_hang_flowMult", _nextFlow, true];
    };
};
if (!isNull _medic) then {
    ["ACME_hangClaimAck", [_patient, _medic, _episode, _accepted, _epoch, _providerOwner, _now + 6], _medic] call CBA_fnc_targetEvent;
};
_accepted

if (!alive _medic || {_medic getVariable ["ACE_isUnconscious", false]}
    || {!isNull objectParent _medic} || {!(missionNamespace getVariable ["ACME_sys_hang", true])}) exitWith {
    [_medic] call ACME_fnc_hangBagPrepStop;

// A monotonic episode distinguishes even a same-frame cancel/restart. Only the owner
// writes patient custody/flow; replicated provider Active is not the acquisition lock.
private _episode = serverTime max ((_medic getVariable ["ACME_hang_Start", -1]) + 0.001);

_medic setVariable ["ACME_hang_Claimed", false, false];
_medic setVariable ["ACME_hang_ClaimRequestedAt", serverTime, false];
_medic setVariable ["ACME_hang_ClaimAckAt", serverTime, false];
_medic setVariable ["ACME_hang_ClaimEpoch", [_patient] call ACME_fnc_clinicalEpoch, false];
_medic setVariable ["ACME_hang_ClaimOwner", owner _medic, false];
_medic setVariable ["ACME_hang_PlayerBound", hasInterface && {_medic isEqualTo ACE_player}, false];

[_patient, "hangBagClaim", [_medic, _episode,
    missionNamespace getVariable ["ACME_hang_flowMult", 1.75],
    _medic getVariable ["ACME_hang_ClaimEpoch", -1], owner _medic]] call ACME_fnc_ownerDispatch;

// A pending claim owns no props or held pose. Cancel it without touching the prior
// episode's captured visual teardown, and restore prep-held weapons even after death.
if !(_medic getVariable ["ACME_hang_Claimed", false]) exitWith {
    _medic setVariable ["ACME_hang_Active", false, true];
    private _pendingPFH = _medic getVariable ["ACME_hang_PFH", -1];
    if (_pendingPFH >= 0) then {[_pendingPFH] call CBA_fnc_removePerFrameHandler;};
    _medic setVariable ["ACME_hang_PFH", -1];
    {[_x, "keydown"] call CBA_fnc_removeKeyHandler;} forEach (_medic getVariable ["ACME_hang_KeyIDs", []]);
    _medic setVariable ["ACME_hang_KeyIDs", []];
    [_patient, "hangBagRelease", [_medic, _episodeStart]] call ACME_fnc_ownerDispatch;
    if (local _medic) then {
        [_medic] call ACME_fnc_hangBagPrepStop;
    } else {
        ["ACME_hangRestoreWeapons", [_medic, _episodeStart], _medic] call CBA_fnc_targetEvent;
    };
};

// The owner reply, not replicated holder writes from another client, determines acceptance.
if ((_medic getVariable ["ACME_hang_ClaimOwner", -1]) != owner _medic
    || {(_medic getVariable ["ACME_hang_ClaimEpoch", -1]) != ([_patient] call ACME_fnc_clinicalEpoch)}
    || {(_medic getVariable ["ACME_hang_PlayerBound", false]) && {!(_medic isEqualTo ACE_player)}}) exitWith {
    [true, _medic] call ACME_fnc_hangBagStop;
};
if !(_medic getVariable ["ACME_hang_Claimed", false]) exitWith {
    if (serverTime - (_medic getVariable ["ACME_hang_ClaimRequestedAt", 0]) >= 5) then {
        [true, _medic] call ACME_fnc_hangBagStop;
    };
};
if (serverTime - (_medic getVariable ["ACME_hang_ClaimAckAt", 0]) >= 6) exitWith {
    [true, _medic] call ACME_fnc_hangBagStop;
};
// Reuse the existing tick, but send at most one renewal every two seconds, never at 20 Hz.
if (serverTime - (_medic getVariable ["ACME_hang_ClaimRequestedAt", 0]) >= 2) then {
    _medic setVariable ["ACME_hang_ClaimRequestedAt", serverTime, false];
    [_patient, "hangBagRenew", [_medic, _medic getVariable ["ACME_hang_Start", -1],
        missionNamespace getVariable ["ACME_hang_flowMult", 1.75],
        _medic getVariable ["ACME_hang_ClaimEpoch", -1], owner _medic]] call ACME_fnc_ownerDispatch;
};

// A local owner can reject the renewal synchronously and stop this episode.
if !(_medic getVariable ["ACME_hang_Active", false]) exitWith {};

private _episodeStart = _unit getVariable ["ACME_hang_Start", -1];
if (!isNull _patient) then {
    [_patient, "hangBagRelease", [_unit, _episodeStart]] call ACME_fnc_ownerDispatch;

case "hangBagClaim": {isNil {[_patient, "claim", _args] call ACME_fnc_hangBagClaimLocal;};};
case "hangBagRenew": {isNil {[_patient, "renew", _args] call ACME_fnc_hangBagClaimLocal;};};
case "hangBagRelease": {isNil {[_patient, "release", _args] call ACME_fnc_hangBagClaimLocal;};};

if (_hangLease >= 0) then {
    !alive _hangMedic || {_hangMedic getVariable ["ACE_isUnconscious", false]}
    || {_netNow >= _hangLease}
    || {(_patient getVariable ["ACME_hang_LeaseEpoch", -1]) != ([_patient] call ACME_fnc_clinicalEpoch)}
} else {
    !alive _hangMedic || {!(_hangMedic getVariable ["ACME_hang_Active", false])}
    || {!((_hangMedic getVariable ["ACME_hang_Patient", objNull]) isEqualTo _patient)}
    || {_hangMedic getVariable ["ACE_isUnconscious", false]}
}
